local UIVideoPlayer = Class('UIVideoPlayer')

------------ import ------------
local KTool = CS.Engine.Lib.KTool
local CommonButtonNode = CS.Game.Native.Common.CommonButtonNode
local ImageAlterable = CS.Engine.UI.ImageAlterable

local UIModule = CS.Engine.UI.UIModule
------------ import ------------

function UIVideoPlayer:__init()
    self.startCb = nil
    self.finishCb = nil
end

function UIVideoPlayer:__delete()
    self.startCb = nil
    self.finishCb = nil
end

function UIVideoPlayer:Awake()
    --self.controller.ClearCache = false
    SetButtonAction(self.Bg, Bind(self, self.OnSkip))
    --默认关掉点击按钮
    KTool.SetActive(self.Bg, false)

    --开始回掉
    self.Node:started('+', function()
        print("开始了")
        if self.startCb then
            self.startCb()
        end
    end)
    --结束回调
    self.Node:loopPointReached('+', function()
        print("结束了")
        KTool.SafeDelete(self.controller.gameObject)
        if self.finishCb then
            self.finishCb()
        end
    end)
    self.Node:errorReceived('+', function(sourcem, errStr)
        printError("播放视频错误："..errStr)
        if self.startCb then
            self.startCb()
        end
        KTool.SafeDelete(self.controller.gameObject)
        if self.finishCb  then
            self.finishCb()
        end
    end)
    self.Node:prepareCompleted('+', function()
        if self.loadFinishCb then
            self.loadFinishCb()
        end
    end)
end

