---PlayVideoWithClip clip资源
---@param clip System.Object
---@param startCb fun():void @ 确定回调
---@param finishCb fun():void @ 取消回调
---@param loadFinishCb fun():void @ 加载完回调
---@param isAutoPlay boolean @ 是否自动播放
---@param loader Engine.Modules.AbstractResourceLoader
function UIVideoPlayer:PlayVideoWithClip(clip, startCb, finishCb, loadFinishCb, isAutoPlay, loader)
    self.loader = loader
    if isNull(clip) then
        if startCb then
            startCb()
        end
        
        if finishCb then
            finishCb()
        end
        KTool.SafeDelete(self.controller.gameObject)
        return
    end

    self.startCb = startCb
    self.finishCb = finishCb

    --camera的方式
    self.Node.source = CS.UnityEngine.Video.VideoSource.VideoClip
    self.Node.playOnAwake = false
    self.Node.controlledAudioTrackCount = 1
    self.Node:EnableAudioTrack(0, true)
    self.Node.targetCamera = UIModule.RootCanvas.defaultCamera

    --"http://vfx.mtime.cn/Video/2019/03/21/mp4/190321153853126488.mp4"
    self.Node.clip = clip
    if isAutoPlay then
        self.Node:Play()
    end
end

---PlayVideoWithRawImage rawimage模式
---@param url string
---@param startCb fun():void @ 确定回调
---@param finishCb fun():void @ 取消回调
---@param loadFinishCb fun():void @ 加载完回调
---@param isAutoPlay boolean @ 是否自动播放
---@param width integer
---@param height integer
---@param loader Engine.Modules.AbstractResourceLoader
function UIVideoPlayer:PlayVideoWithRawImage(url, startCb, finishCb, loadFinishCb, isAutoPlay, width, height, loader)
    self.loader = loader
    --这个模式打开关闭按钮
    KTool.SetActive(self.Bg, true)

    if string.isEmpty(url) then
        if startCb then
            startCb()
        end
    
        if finishCb then
            finishCb()
        end
        KTool.SafeDelete(self.controller.gameObject)

        return
    end
        
    self.startCb = startCb 
    self.finishCb = finishCb 
    --rawimage的方式
    local rawImage = self.Node:GetComponent("RawImage")
    rawImage.enabled = true

    self.Node.playOnAwake = false
    self.Node.renderMode = CS.UnityEngine.Video.VideoRenderMode.RenderTexture
    self.Node.controlledAudioTrackCount = 1
    self.Node:EnableAudioTrack(0, true)
    self.Node.targetCamera = UIModule.RootCanvas.defaultCamera
    self.renderTexture = CS.UnityEngine.RenderTexture.GetTemporary(500, 500, 16, CS.UnityEngine.RenderTextureFormat.ARGBHalf);
    self.Node.targetTexture = self.renderTexture
    rawImage.texture = self.Node.targetTexture
    
    --"http://vfx.mtime.cn/Video/2019/03/21/mp4/190321153853126488.mp4"
    self.Node.url = url
    if isAutoPlay then
        self.Node:Play()
    end
end

function UIVideoPlayer:OnSkip()
    print("结束了")
    KTool.SafeDelete(self.controller.gameObject)
    if self.finishCb  then
        self.finishCb()
    end
end

--暂停
function UIVideoPlayer:Pause()
    self.Node:Pause()
end

--播放
function UIVideoPlayer:Play()
    self.Node:Play()
end

function UIVideoPlayer:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release()
        self.loader = nil
    end

    if self.renderTexture then
        CS.UnityEngine.RenderTexture.ReleaseTemporary(self.renderTexture)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIVideoPlayer